SELECT * FROM {{$Источник (таблица или файл)=}} {{$Лимит строк=LIMIT 200}}

SELECT department_id, job_id, AVG(salary) AS avg_sal FROM employees GROUP BY CUBE (department_id, job_id);
SELECT country, city, SUM(revenue) AS revenue FROM store_sales GROUP BY ROLLUP (country, city);
SELECT year, region, category, SUM(amount) AS total_sales FROM sales GROUP BY GROUPING SETS ((year, region, category), (year, region), (year), ());

SELECT user_id, argMax(status, updated_at) AS current_status, argMax(ip, updated_at) AS last_ip FROM user_status_logs GROUP BY user_id;
SELECT order_id, prices, arrayFilter(x -> x > 100, prices) AS expensive_items, arrayMap(x -> x * 1.2, prices) AS prices_with_vat FROM orders_dump;
SELECT user_id, groupArray(action) AS actions_seq, groupUniqArray(page_id) AS pages FROM user_clicks GROUP BY user_id;
SELECT user_id, tag, event_time FROM user_actions ARRAY JOIN tags AS tag WHERE event_date = today();

SELECT bitmapCardinality(bitmapAnd(groupBitmapState(user_id), (SELECT groupBitmapState(user_id) FROM user_actions WHERE action = 'purchase'))) AS conversion;
SELECT service_name, quantilesExact(0.50, 0.90, 0.95, 0.99)(response_time_ms) AS latency_p FROM http_requests_log WHERE event_date = today() GROUP BY service_name;

SELECT toStartOfHour(event_time) AS hour_bucket, platform, uniqExact(user_id) AS active_users, count() AS total_hits 
FROM events_log WHERE event_date >= today() - 7 GROUP BY hour_bucket, platform ORDER BY hour_bucket DESC;

SELECT domain(url) AS site_domain, extractURLParameter(url, 'utm_source') AS utm_source, count() AS visits 
FROM web_traffic GROUP BY site_domain, utm_source ORDER BY visits DESC;

SELECT id, greatCircleDistance(37.6173, 55.7558, lon, lat) AS dist_m FROM locations WHERE dist_m < 5000;
SELECT event_time, user_id, neighbor(event_time, -1) AS prev_event_time, neighbor(event_time, 1) AS next_event_time FROM user_events ORDER BY event_time;

CREATE DICTIONARY default.user_dict ( id UInt64, country String ) 
PRIMARY KEY id SOURCE(MYSQL(HOST '127.0.0.1' PORT 3306 USER 'root' PASSWORD 'pass' DB 'app' TABLE 'users')) LIFETIME(MIN 300 MAX 600) LAYOUT(HASHED());

SELECT user_id, dictGet('users_dictionary', 'country_code', toUInt64(user_id)) AS country, count() AS total_requests FROM requests_stream GROUP BY user_id, country;
SELECT page_id, count() * 10 AS estimated_views FROM web_analytics SAMPLE 0.1 WHERE event_date = today() GROUP BY page_id;
SELECT user_id, email, updated_at FROM users_replica FINAL WHERE is_active = 1 LIMIT 10 BY user_id;

CREATE TABLE IF NOT EXISTS metrics_log (metric_date Date, device_id UUID, value Float64, created_at DateTime) 
ENGINE = MergeTree() PARTITION BY toYYYYMM(metric_date) ORDER BY (device_id, metric_date, created_at) TTL metric_date + INTERVAL 3 MONTH;

CREATE MATERIALIZED VIEW mv_hourly_stats ENGINE = SummingMergeTree() ORDER BY (hour, device) AS 
SELECT toStartOfHour(event_time) AS hour, device, count() AS cnt FROM events GROUP BY hour, device;
ALTER TABLE events ADD PROJECTION proj_by_user (SELECT user_id, event_type, count() GROUP BY user_id, event_type);

SELECT country, COUNT(*) AS total_rows, ROUND(AVG(price), 2) AS avg_price 
FROM read_parquet('https://d37ci6vzurychx.cloudfront.net/trip-data/yellow_tripdata_2024-01.parquet') 
WHERE passenger_count > 0 GROUP BY country ORDER BY total_rows DESC LIMIT 20;

SELECT * FROM read_json_auto('s3://my-bucket/logs/*.json.gz', format='newline_delimited');
SELECT * FROM sniff_csv('unstructured_data.csv');
COPY (SELECT year(order_date) AS yr, SUM(total) AS rev FROM orders GROUP BY yr) TO 'analytics_summary.parquet' (FORMAT PARQUET, COMPRESSION ZSTD);
COPY (SELECT * FROM orders WHERE status = 'completed') TO 'completed_orders.csv' (HEADER, DELIMITER ';', ENCODING 'UTF-8');

SELECT id, COLUMNS('^sales_.*') * 1.15 AS sales_with_bonus, COLUMNS('date|time') FROM monthly_report;
SELECT * EXCLUDE (internal_hash, secret_key), REPLACE (LOWER(email) AS email) FROM user_credentials;
SELECT list_transform([1, 2, 3, 4, 5], x -> x * 2) AS doubled_numbers, list_filter([10, 15, 20, 25], x -> x >= 18) AS adults_only;
SELECT struct_pack(id := 101, name := 'Item A', meta := map(['tag1', 'tag2'], [10, 20])) AS payload;
PIVOT sales_data ON quarter USING SUM(amount) GROUP BY year, region;

ATTACH 'production.db' AS prod_db (READ_ONLY); 
CREATE SECRET postgres_secret_one (TYPE postgres, HOST '127.0.0.1', PORT 5432, DATABASE postgres, USER 'postgres', PASSWORD '');
SUMMARIZE SELECT * FROM read_parquet('analytics.parquet');
SELECT * FROM sales_2023 UNION ALL BY NAME SELECT * FROM sales_2024;
INSTALL spatial; LOAD spatial; SELECT ST_Point(lon, lat) AS geom FROM locations;

WITH block_info AS (SELECT CAST(block_size AS BIGINT) AS block_size FROM pragma_database_size()), 
table_storage AS (SELECT COUNT(DISTINCT block_id) AS num_blocks FROM pragma_storage_info('table')) 
SELECT ((num_blocks*block_size)/1024/1024)::TEXT||' MB' AS size_in_mb FROM block_info, table_storage;

SELECT c.id AS category_id, c.name AS category_name, p.id AS product_id, p.name AS product_name, p.price FROM categories c 
CROSS JOIN LATERAL (SELECT id, name, price FROM products WHERE category_id = c.id ORDER BY price DESC LIMIT 3) p;

SELECT DISTINCT ON (user_id) user_id, amount, created_at FROM orders ORDER BY user_id, created_at DESC;
WITH RECURSIVE org_tree AS (SELECT id, name, manager_id, 1 AS depth FROM employees WHERE manager_id IS NULL 
UNION ALL SELECT e.id, e.name, e.manager_id, t.depth + 1 FROM employees e INNER JOIN org_tree t ON e.manager_id = t.id) 
SELECT * FROM org_tree ORDER BY depth, name;

SELECT id, metadata->>'device' AS device_type, metadata->'user'->>'email' AS user_email, metadata->'tags' AS tags_array 
FROM audit_logs WHERE metadata @> '{"status": "failed"}' AND metadata->'settings'->>'notifications' = 'true';

SELECT id, payload FROM audit_logs WHERE jsonb_path_exists(payload, '$.items[*].price ? (@ > 1000)');
SELECT title, ts_rank(to_tsvector('russian', body), query) AS rank 
FROM articles, to_tsquery('russian', ' ') query WHERE to_tsvector('russian', body) @@ query ORDER BY rank DESC;

SELECT u.id AS user_id, u.email, ARRAY_AGG(r.role_name) AS roles_list, STRING_AGG(r.role_name, ', ') AS roles_string 
FROM users u JOIN user_roles ur ON u.id = ur.user_id JOIN roles r ON ur.role_id = r.id GROUP BY u.id, u.email;

SELECT category_id, COUNT(*) AS total_count, COUNT(*) FILTER (WHERE price > 1000) AS expensive_count, SUM(price) FILTER (WHERE is_active = true) AS active_sum 
FROM products GROUP BY category_id;

INSERT INTO user_stats (user_id, views_count, last_visit) VALUES (1024, 1, NOW()) ON CONFLICT (user_id) 
DO UPDATE SET views_count = user_stats.views_count + 1, last_visit = EXCLUDED.last_visit;

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_active_users ON orders (user_id, created_at DESC) WHERE status = 'active';
CREATE TABLE orders_y2025 PARTITION OF orders FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
SELECT pg_try_advisory_lock(100200300) AS lock_acquired; SELECT pg_advisory_unlock(100200300);

SELECT generate_series('2025-01-01'::date, '2025-01-31'::date, '1 day'::interval)::date AS calendar_day;
SELECT id, title, booking_range FROM reservations WHERE booking_range @> '2025-07-15'::date;
SELECT id, name, price FROM products TABLESAMPLE SYSTEM (10) REPEATABLE (42);

SELECT country, year, sales FROM sales_data MODEL PARTITION BY (country) DIMENSION BY (year) MEASURES (sales) RULES (sales[2026] = sales[2025] * 1.10);

SELECT * FROM stock_prices MATCH_RECOGNIZE (
PARTITION BY symbol ORDER BY trade_time MEASURES STRT.price AS start_price, LAST(DOWN.price) AS bottom_price 
PATTERN (STRT DOWN+ UP+) DEFINE DOWN AS DOWN.price < PREV(DOWN.price), UP AS UP.price > PREV(UP.price)
);

SELECT LEVEL, employee_id, first_name || ' ' || last_name AS name, manager_id, SYS_CONNECT_BY_PATH(last_name, '/') AS tree_path 
FROM employees START WITH manager_id IS NULL CONNECT BY PRIOR employee_id = manager_id ORDER SIBLINGS BY last_name;

SELECT LEVEL AS day_seq, TRUNC(SYSDATE, 'MM') + LEVEL - 1 AS calc_date FROM DUAL CONNECT BY LEVEL <= 31;

SELECT j.book_id, j.title, j.author 
FROM book_store b, JSON_TABLE(b.json_data, '$.books[*]' COLUMNS (book_id PATH '$.id', title PATH '$.title', author PATH '$.author')) j;

UPDATE user_profiles SET profile_json = JSON_TRANSFORM(profile_json, SET '$.status' = 'ACTIVE', REMOVE '$.temp_token') WHERE user_id = 5001;
SELECT department_id, LISTAGG(first_name || ' ' || last_name, ', ') WITHIN GROUP (ORDER BY salary DESC) AS top_employees FROM employees GROUP BY department_id;
SELECT /*+ RESULT_CACHE */ category_id, COUNT(*), AVG(price) FROM catalog_products GROUP BY category_id;
SELECT * FROM employees AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL '30' MINUTE) WHERE employee_id = 101;

CREATE OR REPLACE TRIGGER trg_emp_audit FOR UPDATE ON employees COMPOUND TRIGGER BEFORE STATEMENT IS BEGIN NULL; END BEFORE STATEMENT; END;
CREATE GLOBAL TEMPORARY TABLE gtt_session_cart (item_id NUMBER, qty NUMBER) ON COMMIT PRESERVE ROWS;
ALTER INDEX idx_emp_salary INVISIBLE;
CREATE TABLE app_users (user_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, username VARCHAR2(100) NOT NULL);

CREATE OR REPLACE PROCEDURE get_dept_employees (p_dept_id IN NUMBER, p_cursor OUT SYS_REFCURSOR) AS 
BEGIN OPEN p_cursor FOR SELECT employee_id, first_name, salary FROM employees WHERE department_id = p_dept_id; END;
